import json
from pathlib import Path

from main import app


def test_openapi_contract_conforms():
    """Verify that FastAPI's autogenerated OpenAPI spec matches our checked-in openapi.json.
    This prevents accidental breaking API changes without updating the contract.
    """
    repo_root = Path(__file__).resolve().parent.parent
    contract_path = repo_root / "openapi.json"
    
    assert contract_path.exists(), "openapi.json contract file does not exist!"
    
    with open(contract_path, "r", encoding="utf-8") as f:
        contract_spec = json.load(f)
        
    current_spec = app.openapi()
    
    # Check openapi version and title
    assert current_spec.get("openapi") == contract_spec.get("openapi")
    assert current_spec.get("info", {}).get("title") == contract_spec.get("info", {}).get("title")
    
    # Compare paths
    current_paths = current_spec.get("paths", {})
    contract_paths = contract_spec.get("paths", {})
    
    assert set(current_paths.keys()) == set(contract_paths.keys()), \
        f"API paths mismatch! Current: {set(current_paths.keys())}, Contract: {set(contract_paths.keys())}"
        
    for path, methods in contract_paths.items():
        current_methods = current_paths.get(path, {})
        assert set(current_methods.keys()) == set(methods.keys()), \
            f"Methods mismatch for path {path}! Current: {set(current_methods.keys())}, Contract: {set(methods.keys())}"
